import React, { PropsWithChildren, useRef } from 'react';

import { item, itemWrapper } from './styles.sty.js';
import { uuidv4 } from '../../../../../core/utils/uuidv4.js';
import { Divider } from '../../../../../typography/Divider.js';
import { ChartActionsMenu } from '../../series-action/ChartActionsMenu.js';
import { useActionSelection } from '../context/ActionSelectionContext.js';
import { TooltipItemProps } from '../types/ChartTooltip.config.js';

export const TooltipItem = (props: PropsWithChildren<TooltipItemProps>) => {
  const { children, showDivider, actions, ...rest } = props;
  const itemIdRef = useRef(uuidv4());

  const { selectedItemId, actionsMenuRef, updateSelectedItem } =
    useActionSelection();

  if (!actions) {
    return (
      <>
        <div className={item} {...rest}>
          {children}
        </div>
        {showDivider && <Divider orientation="horizontal" />}
      </>
    );
  }

  return (
    <ChartActionsMenu
      isOpen={selectedItemId === itemIdRef.current}
      actions={actions}
      onActionClick={() => updateSelectedItem('')}
      ref={actionsMenuRef}
    >
      <button
        className={itemWrapper}
        onMouseOver={() => updateSelectedItem(itemIdRef.current)}
      >
        <div className={item} {...rest}>
          {children}
        </div>
        {showDivider && <Divider orientation="horizontal" />}
      </button>
    </ChartActionsMenu>
  );
};

TooltipItem['displayName'] = 'TooltipItem';
